import{_ as a,o as r,c as s,a5 as n}from"./chunks/framework.a5no_H3L.js";const u=JSON.parse('{"title":"C# 并发诊断：死锁、线程池饥饿与异步卡死","description":"本页回答三个问题：请求卡死时如何判断是死锁还是线程池饥饿，async 方法「没执行完」如何定位，如何采集并发现场的证据。机制见并发异步。","frontmatter":{"type":"explanation","level":"advanced"},"headers":[],"relativePath":"csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md","filePath":"csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"}'),e={name:"csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"};function i(t,c,o,d,l,h){return r(),s("div",null,[...c[0]||(c[0]=[n(`<h1 id="c-并发诊断-死锁、线程池饥饿与异步卡死" tabindex="-1" data-src-line="2" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">C# 并发诊断：死锁、线程池饥饿与异步卡死 <a class="header-anchor" href="#c-并发诊断-死锁、线程池饥饿与异步卡死" aria-label="Permalink to &quot;C# 并发诊断：死锁、线程池饥饿与异步卡死&quot;">​</a></h1><p data-src-line="4" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">本页回答三个问题：请求卡死时如何判断是死锁还是线程池饥饿，<code>async</code> 方法「没执行完」如何定位，如何采集并发现场的证据。机制见<a href="./../../03-csharp-concurrency/chapter-01-why-async.html">并发异步</a>。</p><h2 id="_1-先分清卡死类型" tabindex="-1" data-src-line="6" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">1. 先分清卡死类型 <a class="header-anchor" href="#_1-先分清卡死类型" aria-label="Permalink to &quot;1. 先分清卡死类型&quot;">​</a></h2><p data-src-line="8" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">请求卡死有三种常见根因：</p><ul data-src-line="10" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><li data-src-line="10" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><strong>死锁</strong>：两个线程各自持锁又等对方（见<a href="./../../03-csharp-concurrency/chapter-04-threading-synchronization.html">线程与同步</a>）。</li><li data-src-line="11" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><strong>线程池饥饿</strong>：大量任务阻塞线程池线程，新任务排队等不到线程。</li><li data-src-line="12" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><strong>异步死锁</strong>：同步阻塞 <code>.Result</code>/<code>.Wait()</code> 与同步上下文冲突（见<a href="./../../03-csharp-concurrency/chapter-06-concurrency-pitfalls.html">常见并发缺陷</a>）。</li></ul><p data-src-line="14" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">三者表象都是「卡住」，但证据不同：死锁是锁竞争，饥饿是线程池队列堆积，异步死锁是同步上下文回不去。</p><h2 id="_2-采集现场" tabindex="-1" data-src-line="16" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">2. 采集现场 <a class="header-anchor" href="#_2-采集现场" aria-label="Permalink to &quot;2. 采集现场&quot;">​</a></h2><p data-src-line="18" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">用 <code>dotnet-dump</code> 采集转储，分析线程状态：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotnet-dump collect --process-id &lt;pid&gt;</span></span></code></pre></div><p data-src-line="24" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">转储分析能看到每个线程正在等待什么：等锁、等 I/O、还是在线程池队列排队。用 <code>dotnet-trace</code> 也能观察线程池指标：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>dotnet-counters monitor --process-id &lt;pid&gt; System.Runtime</span></span></code></pre></div><p data-src-line="30" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">关注 <code>ThreadPool Queue Length</code>（线程池队列长度）和 <code>ThreadPool Thread Count</code>（线程数）。队列长度持续增长而线程数不涨，是线程池饥饿的典型信号。</p><h2 id="_3-定位死锁" tabindex="-1" data-src-line="32" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">3. 定位死锁 <a class="header-anchor" href="#_3-定位死锁" aria-label="Permalink to &quot;3. 定位死锁&quot;">​</a></h2><p data-src-line="34" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">转储中两个线程互相等待对方持有的锁，是死锁的直接证据。分析时找：</p><ul data-src-line="36" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><li data-src-line="36" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">哪些线程在 <code>Monitor.Enter</code>/<code>lock</code> 等待。</li><li data-src-line="37" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">这些锁被哪些线程持有。</li><li data-src-line="38" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">是否形成环。</li></ul><p data-src-line="40" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">修复方向：统一加锁顺序、减少锁的数量、缩小临界区。详见<a href="./../../03-csharp-concurrency/chapter-04-threading-synchronization.html">线程与同步</a>。</p><h2 id="_4-定位线程池饥饿" tabindex="-1" data-src-line="42" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">4. 定位线程池饥饿 <a class="header-anchor" href="#_4-定位线程池饥饿" aria-label="Permalink to &quot;4. 定位线程池饥饿&quot;">​</a></h2><p data-src-line="44" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">饥饿的根因通常是：在线程池线程上同步阻塞等待异步操作。</p><div class="language-csharp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">csharp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 反例：线程池线程上同步等待</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">string</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> content</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> FetchAsync</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">().Result;</span></span></code></pre></div><p data-src-line="51" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">线程池线程被 <code>.Result</code> 阻塞，异步操作完成后又要线程池线程来恢复，但线程都被占住，形成饥饿。证据是大量线程阻塞在 <code>.Wait</code>/<code>.Result</code>，同时线程池队列堆积。</p><p data-src-line="53" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">修复：消除同步阻塞，一路 <code>async/await</code>（见<a href="./../../03-csharp-concurrency/chapter-02-task-async-await.html">Task 与 async/await</a>）。</p><h2 id="_5-定位-async-卡死" tabindex="-1" data-src-line="55" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">5. 定位 async 卡死 <a class="header-anchor" href="#_5-定位-async-卡死" aria-label="Permalink to &quot;5. 定位 async 卡死&quot;">​</a></h2><p data-src-line="57" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><code>async</code> 方法「没执行完」或卡死，常见根因：</p><ul data-src-line="59" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><li data-src-line="59" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">同步上下文死锁（UI 线程 <code>.Result</code>）。</li><li data-src-line="60" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">未 <code>await</code> 的 <code>Task</code> 被丢弃（任务泄漏）。</li><li data-src-line="61" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">死循环中的 <code>await</code> 永远不完成。</li></ul><p data-src-line="63" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">转储中看 <code>async</code> 状态机的暂停点：方法停在哪个 <code>await</code>，等待的 <code>Task</code> 是否完成。结合日志确认调用链是否 <code>async</code> 到底。</p><h2 id="_6-排查顺序" tabindex="-1" data-src-line="65" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">6. 排查顺序 <a class="header-anchor" href="#_6-排查顺序" aria-label="Permalink to &quot;6. 排查顺序&quot;">​</a></h2><ol data-src-line="67" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><li data-src-line="67" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">确认现象是「卡死」还是「慢」，是偶发还是必现。</li><li data-src-line="68" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">采集转储和线程池指标，定位是锁等待、队列堆积还是同步上下文问题。</li><li data-src-line="69" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">找到根因代码，修复后用小范围压测复现验证。</li><li data-src-line="70" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">并发问题难复现，修复要辅以日志和监控，而不是只依赖一次通过。</li></ol><h2 id="_7-后续阅读" tabindex="-1" data-src-line="72" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">7. 后续阅读 <a class="header-anchor" href="#_7-后续阅读" aria-label="Permalink to &quot;7. 后续阅读&quot;">​</a></h2><ul data-src-line="74" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><li data-src-line="74" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><a href="./../../03-csharp-concurrency/chapter-04-threading-synchronization.html">线程与同步</a>解释锁与原子操作。</li><li data-src-line="75" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><a href="./../../03-csharp-concurrency/chapter-02-task-async-await.html">Task 与 async/await</a>解释同步上下文。</li><li data-src-line="76" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><a href="./../../03-csharp-concurrency/chapter-06-concurrency-pitfalls.html">常见并发缺陷</a>汇总死锁与饥饿的模式。</li><li data-src-line="77" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><a href="./chapter-02-threadpool-starvation-case.html">线程池饥饿案例</a>看一次 <code>.Result</code> 阻塞的完整排查。</li></ul><blockquote data-src-line="79" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md"><p data-src-line="79" data-src-file="csharp/07-diagnostics/02-concurrency/chapter-01-concurrency-diagnostics.md">本页的技术边界按 .NET 10 / C# 14 核对；<code>dotnet-dump</code>、<code>dotnet-counters</code> 随 .NET SDK 提供。官方参考：<a href="https://learn.microsoft.com/en-us/dotnet/core/diagnostics/" target="_blank" rel="noreferrer">.NET 诊断</a>、<a href="https://learn.microsoft.com/en-us/dotnet/core/diagnostics/debug-deadlock" target="_blank" rel="noreferrer">分析死锁</a>。</p></blockquote>`,30)])])}const y=a(e,[["render",i]]);export{u as __pageData,y as default};
